def nl_of(t): return "\r\n" if "\r\n" in t else "\n"
def read(p): return open(p, encoding="utf-8", newline="").read()
def write(p, t):
    os.makedirs(os.path.dirname(p) or ".", exist_ok=True)
    with open(p, "w", encoding="utf-8", newline="") as f: f.write(t)

def hint(path, text): print("  !! could not find the place to edit in", path, "- add this by hand:\n     " + text.strip().replace("\n", "\n     "))

def insert_after(path, marker, anchor, text):
    s = read(path); nl = nl_of(s)
    if marker in s: print("  already done:", path); return
    m = re.search(anchor, s, re.M)
    if not m: return hint(path, text)
    pos = m.end() - (1 if s[m.end() - 1:m.end()] == "\r" else 0)
    write(path, s[:pos] + nl + text.replace("\n", nl).rstrip("\r\n") + s[pos:]); print("  edited:", path)

def insert_before(path, marker, anchor, text):
    s = read(path); nl = nl_of(s)
    if marker in s: print("  already done:", path); return
    m = re.search(anchor, s, re.M)
    if not m: return hint(path, text)
    write(path, s[:m.start()] + text.replace("\n", nl).rstrip("\r\n") + nl + s[m.start():]); print("  edited:", path)

def replace(path, marker, old, new, count=1):
    s = read(path); nl = nl_of(s)
    if marker in s: print("  already done:", path); return
    old_n = old.replace("\n", nl)          # your file may use Windows (CRLF) line endings
    if s.count(old_n) < 1: return hint(path, "replace:  " + old + "\n     with:     " + new)
    write(path, s.replace(old_n, new.replace("\n", nl), count)); print("  edited:", path)

def append(path, marker, text):
    s = read(path); nl = nl_of(s)
    if marker in s: print("  already done:", path); return
    write(path, s.rstrip("\r\n") + nl + nl + text.replace("\n", nl) + nl); print("  edited:", path)

